-- SaaS/commercial foundation deployed to production 2026-09-17.
-- Canonical schema: invoices + immutable adjustments + subscription plans + company subscriptions.
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,placement_id uuid references public.placements(id) on delete set null,client_id uuid not null references public.clients(id) on delete restrict,number text not null,status text not null default 'draft' check(status in ('draft','sent','part_paid','paid','overdue','void')),currency char(3) not null default 'GBP',subtotal numeric(14,2) not null default 0,tax_rate numeric(6,3) not null default 0,tax_amount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,amount_paid numeric(14,2) not null default 0,amount_due numeric(14,2) generated always as (greatest(total-amount_paid,0)) stored,issue_date date,due_date date,sent_at timestamptz,paid_at timestamptz,voided_at timestamptz,notes text,external_provider text,external_id text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,number));
create table if not exists public.invoice_adjustments(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,invoice_id uuid not null references public.invoices(id) on delete cascade,kind text not null check(kind in ('payment','credit','refund','write_off','correction')),amount numeric(14,2) not null check(amount>0),reason text not null,reference text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.saas_plans(code text primary key,name text not null,monthly_price_gbp numeric(10,2) not null default 0,recruiter_limit int,active_job_limit int,candidate_limit int,automation_limit int,features jsonb not null default '{}'::jsonb,active boolean not null default true);
create table if not exists public.company_subscriptions(company_id uuid primary key references public.companies(id) on delete cascade,plan_code text not null references public.saas_plans(code),status text not null default 'trialing' check(status in ('trialing','active','past_due','cancelled','suspended')),trial_ends_at timestamptz,current_period_start timestamptz,current_period_end timestamptz,provider text,provider_customer_id text,provider_subscription_id text,cancel_at_period_end boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.companies add column if not exists slug text;alter table public.companies add column if not exists onboarding_completed_at timestamptz;alter table public.companies add column if not exists billing_email text;create unique index if not exists companies_slug_unique on public.companies(lower(slug)) where slug is not null;
-- RLS and operational RPCs are installed in production by the matching Supabase migrations saas_commercial_billing_foundation + saas_onboarding_invoice_operations.
